/*!50003 CREATE*/ /*!50017 DEFINER=`Diego.Garrido`@`%`*/ /*!50003 TRIGGER `trg_tb_people_ai` AFTER INSERT ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        record_id,
        table_operation,
        db_user,
        table_description
    )
    VALUES (
        'tb_people',
        NEW.person_ID,
        'Create',
        CASE SUBSTRING_INDEX(USER(), '@', 1)
            WHEN 'app_web' THEN 'app_web@DESKTOP-DH292'
            WHEN 'app_mobile' THEN 'app_mobile@Samsung-Galaxy-S24'
            ELSE USER()
        END,
        CONCAT('Registro creado en tb_people. ID=', NEW.person_ID)
    );
END */;;
DELIMITER ;
