/*!50003 CREATE*/ /*!50017 DEFINER=`Diego.Garrido`@`%`*/ /*!50003 TRIGGER `trg_users_after_insert` AFTER INSERT ON `tb_users` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        record_id,
        table_operation,
        db_user,
        table_description,
        operation_date,
        operation_status
    )
    VALUES (
        'tb_users',
        NEW.ID,
        'Create',
        CASE SUBSTRING_INDEX(USER(), '@', 1)
            WHEN 'app_web' THEN 'app_web@DESKTOP-DH292'
            WHEN 'app_mobile' THEN 'app_mobile@Samsung-Galaxy-S24'
            ELSE USER()
        END,
        CONCAT(
            'Usuario creado. ID=',
            NEW.ID,
            ', email=',
            NEW.email,
            ', nick=',
            NEW.nick,
            ', creation_date=',
            NEW.creation_date,
            ', status=',
            COALESCE(CAST(NEW.status AS UNSIGNED), 0)
        ),
        CURRENT_TIMESTAMP,
        b'1'
    );
END */;;
