/*!50003 CREATE*/ /*!50017 DEFINER=`Diego.Garrido`@`%`*/ /*!50003 TRIGGER `trg_users_after_update` AFTER UPDATE ON `tb_users` FOR EACH ROW BEGIN
    IF NOT (
        OLD.email <=> NEW.email
        AND OLD.nick <=> NEW.nick
        AND OLD.last_login <=> NEW.last_login
        AND OLD.status <=> NEW.status
    ) THEN

        INSERT INTO tb_logs (
            table_name,
            record_id,
            table_operation,
            db_user,
            table_description,
            operation_date,
            operation_status
        )
        VALUES (
            'tb_users',
            NEW.ID,
            'Update',
            CASE SUBSTRING_INDEX(USER(), '@', 1)
                WHEN 'app_web' THEN 'app_web@DESKTOP-DH292'
                WHEN 'app_mobile' THEN 'app_mobile@Samsung-Galaxy-S24'
                ELSE USER()
            END,
            CONCAT(
                'Usuario actualizado. ID=',
                NEW.ID,
                ', email anterior=',
                OLD.email,
                ', email nuevo=',
                NEW.email,
                ', nick anterior=',
                OLD.nick,
                ', nick nuevo=',
                NEW.nick,
                ', last_login anterior=',
                COALESCE(CAST(OLD.last_login AS CHAR), 'NULL'),
                ', last_login nuevo=',
                COALESCE(CAST(NEW.last_login AS CHAR), 'NULL'),
                ', status anterior=',
                COALESCE(CAST(OLD.status AS UNSIGNED), 0),
                ', status nuevo=',
                COALESCE(CAST(NEW.status AS UNSIGNED), 0)
            ),
            CURRENT_TIMESTAMP,
            b'1'
        );

    END IF;
END */;;
DELIMITER ;
