        table_name,
        record_id,
        table_operation,
        db_user,
        table_description,
        operation_date,
        operation_status
    )
    VALUES (
        'tb_users',
        OLD.ID,
        'Delete',
        CASE SUBSTRING_INDEX(USER(), '@', 1)
            WHEN 'app_web' THEN 'app_web@DESKTOP-DH292'
            WHEN 'app_mobile' THEN 'app_mobile@Samsung-Galaxy-S24'
            ELSE USER()
        END,
        CONCAT(
            'Usuario eliminado. ID=',
            OLD.ID,
            ', email=',
            OLD.email,
            ', nick=',
            OLD.nick,
            ', creation_date=',
            OLD.creation_date,
            ', last_update=',
            COALESCE(CAST(OLD.last_update AS CHAR), 'NULL'),
            ', last_login=',
            COALESCE(CAST(OLD.last_login AS CHAR), 'NULL'),
            ', status=',
            COALESCE(CAST(OLD.status AS UNSIGNED), 0)
        ),
        CURRENT_TIMESTAMP,
        b'1'
    );
END */;;
